from adr.dist import Mixture, Normal, tanh, exp, dot


def model(x):
    v0 = x[[27, 70, 44, 40, 68, 29]]
    v1 = x[[54, 46, 17, 19, 74, 33]]
    h0 = tanh(0.668362 + dot(v0, [-0.00964714, -0.00230429, 0.00820028, 0.000134369, 0.00517367, 0.00833773]) + dot(v1, [-0.0123261, 0.00997939, -0.00640715, 0.0154569, -0.255131, 9.71807e-05]) + x[80] * -0.247921)
    h1 = tanh(7.48274 + dot(v0, [0.0135383, 0.0259619, -0.0278472, -9.57942e-05, -0.0224216, -0.00796251]) + dot(v1, [0.185512, -1.01465, 0.0010275, -0.0067068, -4.08107, -0.000367596]) + x[80] * 0.934035)
    h2 = tanh(-3.37069 + dot(v0, [0.0170735, -0.0586521, 0.0376712, 8.47734e-05, 0.0228447, -0.0496235]) + dot(v1, [-0.0194662, 1.32029, -0.00624053, 0.0153379, 2.15896, 0.000911805]) + x[80] * -0.567238)
    return Mixture([exp(-8.50905 - 0.652085 * h0 - 9.73551 * h1 + 0.892906 * h2), exp(5.4034 + 0.427228 * h0 + 4.63002 * h1 + 0.96712 * h2), exp(3.10565 + 0.711607 * h0 + 5.19276 * h1 - 2.09328 * h2)], [Normal(-15.8797 - 10.1154 * h0 - 32.847 * h1 - 2.61752 * h2, exp(-0.00103332 - 0.843445 * h0 - 1.98747 * h1 - 0.116178 * h2)), Normal(34.6741 - 2.7178 * h0 + 7.67541 * h1 - 22.9407 * h2, exp(2.40441 - 0.572056 * h0 + 0.808395 * h1 - 0.821804 * h2)), Normal(108.007 + 14.577 * h0 + 27.5089 * h1 - 4.61929 * h2, exp(3.73089 - 0.161091 * h0 + 1.03186 * h1 + 1.07755 * h2))])
